use deskbox_reconstructed::{layout_backup as b,model::*,state};
use serde_json::json;
fn monitor()->Monitor{Monitor{name:"screen".into(),label:"overlay".into(),x:0,y:0,w:1200,h:800,scale:1.,work:[0.,0.,1200.,800.],primary:true}}
#[test] fn capture_excludes_contents_restore_keeps_live(){
 let mut c=Config::default();let id=state::create_fence(&mut c,"screen",[120.,90.],"Docs","document");c.fences[0].items=vec!["old-file".into()];
 c.widgets.push(Widget{id:"notes".into(),kind:"notes".into(),monitor:"screen".into(),x:50.,y:60.,style:serde_json::from_value(json!({"widgetWidth":420,"widgetData":{"note":"old secret","todos":[{"text":"old"}]}})).unwrap()});
 let backup=b::capture(&c,"first",1234).unwrap();let serialized=serde_json::to_string(&backup).unwrap();assert!(!serialized.contains("old-file"));assert!(!serialized.contains("old secret"));
 c.fences[0].x=500.;c.widgets[0].style["widgetData"]=json!({"note":"latest note","todos":[{"text":"latest"}]});
 let item=Item{id:"new-file".into(),learning_key:None,name:"new.txt".into(),path:"new.txt".into(),kind:"file".into(),ext:"txt".into(),category:"document".into(),icon:None};
 b::restore(&mut c,&backup,&[monitor()],&[item]).unwrap();assert_eq!(c.fences.iter().find(|f|f.id==id).unwrap().x,120.);assert_eq!(c.fences[0].items,vec!["new-file"]);assert_eq!(c.widgets[0].style["widgetData"]["note"],"latest note");assert_eq!(backup.created_at,1234);
}
#[test]fn groups_and_missing_display(){let mut c=Config::default();let a=state::create_fence(&mut c,"gone",[9000.,9000.],"A","document");let z=state::create_fence(&mut c,"gone",[0.,0.],"B","other");deskbox_reconstructed::fence_merge::group(&mut c,&a,&z).unwrap();c.fence_groups[0].x=9000.;let backup=b::capture(&c,"group",42).unwrap();b::restore(&mut c,&backup,&[monitor()],&[]).unwrap();assert_eq!(c.fence_groups[0].monitor,"screen");assert!(c.fence_groups[0].x<=880.);assert!(c.fences.iter().all(|f|f.monitor=="screen"));}
#[test]fn deleted_widget_restores_empty(){let mut c=Config::default();c.widgets.push(Widget{id:"a".into(),kind:"album".into(),monitor:"screen".into(),x:0.,y:0.,style:serde_json::from_value(json!({"widgetData":{"photos":[{"path":"private.jpg"}],"interval":12,"paused":true}})).unwrap()});let backup=b::capture(&c,"photo",4).unwrap();c.widgets.clear();b::restore(&mut c,&backup,&[monitor()],&[]).unwrap();let d=&c.widgets[0].style["widgetData"];assert!(d.get("photos").is_none());assert_eq!(d["interval"],12);}

#[test]fn metadata_persistence_and_invalid_restore_atomic(){let mut c=Config::default();let a=state::create_fence(&mut c,"screen",[30.,40.],"A","document");let mut backups=vec![b::capture(&c,"original",99).unwrap()];let id=backups[0].id.clone();b::rename(&mut backups,&id,"renamed").unwrap();assert_eq!(backups[0].created_at,99);assert!(b::rename(&mut backups,&id,"  ").is_err());let dir=std::env::temp_dir().join(format!("deskbox-layout-test-{}",uuid::Uuid::new_v4()));b::save(&dir,&backups).unwrap();let mut loaded=b::load(&dir).unwrap();assert_eq!(loaded[0].name,"renamed");let before=serde_json::to_value(&c).unwrap();assert!(b::restore(&mut c,&loaded[0],&[],&[]).is_err());assert_eq!(serde_json::to_value(&c).unwrap(),before);assert_eq!(c.fences[0].id,a);b::delete(&mut loaded,&id).unwrap();b::save(&dir,&loaded).unwrap();assert!(b::load(&dir).unwrap().is_empty());std::fs::remove_file(dir.join("layout-backups.json")).unwrap();std::fs::remove_dir(dir).unwrap();}
#[test]fn timer_settings_restore_preserves_running_state(){let mut c=Config::default();c.widgets.push(Widget{id:"timer".into(),kind:"timer".into(),monitor:"screen".into(),x:0.,y:0.,style:serde_json::from_value(json!({"widgetData":{"timer":{"mode":"pomodoro","focusMinutes":25,"running":false,"remaining":99,"deadline":111}}})).unwrap()});let saved=b::capture(&c,"timer",0).unwrap();assert!(saved.widgets[0].style["widgetData"]["timer"].get("remaining").is_none());c.widgets[0].style["widgetData"]["timer"]=json!({"focusMinutes":50,"running":true,"deadline":9999,"phase":"focus"});b::restore(&mut c,&saved,&[monitor()],&[]).unwrap();let t=&c.widgets[0].style["widgetData"]["timer"];assert_eq!(t["focusMinutes"],25);assert_eq!(t["running"],true);assert_eq!(t["deadline"],9999);}

#[test]fn group_fits_largest_member(){let mut c=Config::default();let a=state::create_fence(&mut c,"gone",[0.,0.],"A","document");let z=state::create_fence(&mut c,"gone",[900.,0.],"B","other");c.fences[0].w=1000.;deskbox_reconstructed::fence_merge::group(&mut c,&a,&z).unwrap();let backup=b::capture(&c,"large",0).unwrap();b::restore(&mut c,&backup,&[monitor()],&[]).unwrap();assert!(c.fence_groups[0].x<=200.);}
#[test]fn missing_selected_eco_falls_back(){let dir=std::env::temp_dir().join(format!("deskbox-bg-test-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&dir).unwrap();std::fs::write(dir.join("original.mp4"),b"fixture").unwrap();let mut c=Config::default();state::create_fence(&mut c,"screen",[0.,0.],"A","document");c.fences[0].style.insert("media".into(),json!({"kind":"video","mode":"eco","original":dir.join("original.mp4"),"eco":dir.join("missing.mp4")}));let backup=b::capture(&c,"bg",0).unwrap();assert_eq!(b::restore(&mut c,&backup,&[monitor()],&[]).unwrap(),1);assert!(c.fences[0].style.get("media").is_none());std::fs::remove_file(dir.join("original.mp4")).unwrap();std::fs::remove_dir(dir).unwrap();}
